class Solution {
    public int[] maxDepthAfterSplit(String seq){
        int[] answer=new int[seq.length()];
        int depth=0;
        for(int i=0;i<seq.length();i++)if(seq.charAt(i)=='(')answer[i]=depth++%2;
        else answer[i]=--depth%2;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxDepthAfterSplit(seq:String):IntArray{
        val answer=IntArray(seq.length);
        var depth=0;
        for(i in seq.indices)if(seq[i]=='('){
            answer[i]=depth%2;
            depth++
        }else{
            depth--;
            answer[i]=depth%2
        };
        return answer
    }
}

